CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),username text NOT NULL UNIQUE,password_hash text NOT NULL,timezone text NOT NULL DEFAULT 'UTC',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pair_spaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS pair_members(pair_id uuid NOT NULL REFERENCES pair_spaces(id),user_id uuid NOT NULL REFERENCES users(id),role text NOT NULL DEFAULT 'member',joined_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(pair_id,user_id));
CREATE TABLE IF NOT EXISTS auth_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS moods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),pair_id uuid,system_key text,name text NOT NULL,emoji text,sort_order int NOT NULL DEFAULT 0,archived_at timestamptz);
CREATE TABLE IF NOT EXISTS listening_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),pair_id uuid NOT NULL,user_id uuid NOT NULL,playlist_id uuid,playlist_snapshot_id uuid,mood_id uuid,mood_name_snapshot text NOT NULL,mood_intensity int NOT NULL CHECK(mood_intensity BETWEEN 1 AND 5),visibility text NOT NULL DEFAULT 'full',play_mode text NOT NULL DEFAULT 'ordered',timezone_snapshot text NOT NULL,local_started_date text NOT NULL,status text NOT NULL DEFAULT 'CREATED',started_at timestamptz,last_event_at timestamptz,ended_at timestamptz,client_version text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS playback_instances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL,track_id uuid NOT NULL,sequence int NOT NULL,started_by text NOT NULL,selection_source text NOT NULL,started_at timestamptz NOT NULL DEFAULT now(),initial_position_ms int NOT NULL DEFAULT 0,ended_at timestamptz,end_position_ms int,ended_reason text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(session_id,sequence));
CREATE TABLE IF NOT EXISTS listening_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL,playback_instance_id uuid NOT NULL,track_id uuid NOT NULL,seq int NOT NULL,batch_id uuid NOT NULL,event_type text NOT NULL,position_ms int NOT NULL CHECK(position_ms>=0),client_wall_time timestamptz NOT NULL,client_monotonic_ms int,server_received_at timestamptz NOT NULL DEFAULT now(),schema_version int NOT NULL DEFAULT 1,metadata jsonb NOT NULL DEFAULT '{}',UNIQUE(session_id,seq),UNIQUE(session_id,batch_id));
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid,pair_id uuid,action text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS event_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL,batch_id uuid NOT NULL,event_count int NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(session_id,batch_id));
CREATE TABLE IF NOT EXISTS session_track_stats(session_id uuid NOT NULL,track_id uuid NOT NULL,play_count int NOT NULL DEFAULT 0,total_listen_ms int NOT NULL DEFAULT 0,covered_ms int NOT NULL DEFAULT 0,coverage_ratio numeric(6,5) NOT NULL DEFAULT 0,natural_completion_count int NOT NULL DEFAULT 0,manual_skip_count int NOT NULL DEFAULT 0,early_skip_count int NOT NULL DEFAULT 0,replay_count int NOT NULL DEFAULT 0,return_count int NOT NULL DEFAULT 0,seek_count int NOT NULL DEFAULT 0,hearted_final boolean NOT NULL DEFAULT false,heart_toggle_count int NOT NULL DEFAULT 0,PRIMARY KEY(session_id,track_id));
CREATE TABLE IF NOT EXISTS pair_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),pair_id uuid NOT NULL,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,used_at timestamptz,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS pair_members_user_idx ON pair_members(user_id);
CREATE INDEX IF NOT EXISTS sessions_user_status_idx ON listening_sessions(user_id,status);
CREATE INDEX IF NOT EXISTS events_session_received_idx ON listening_events(session_id,server_received_at);
